package applications

import (
	"encoding/json"
	"errors"
	"os"
	"reflect"
	"testing"
)

// The oracle is generated by real unchanged legacy JS, not by the Go code
// under test. CI verifies the committed vectors against that oracle again.
func TestCreationLegacyContract(t *testing.T) {
	data, err := os.ReadFile("testdata/creation-contract.json")
	if err != nil {
		t.Fatal(err)
	}
	var fixture struct {
		Vectors []struct {
			Name       string
			Input      CreateInput
			Valid      bool
			Normalized CreateInput
			Hash       string
		}
	}
	if err := json.Unmarshal(data, &fixture); err != nil {
		t.Fatal(err)
	}
	if len(fixture.Vectors) < 40 {
		t.Fatal("legacy contract vectors missing")
	}
	for _, vector := range fixture.Vectors {
		t.Run(vector.Name, func(t *testing.T) {
			input := vector.Input
			input.IdempotencyKey = testKey
			got, err := input.normalize()
			if !vector.Valid {
				if !errors.Is(err, ErrInvalidInput) {
					t.Fatal("Go accepted an input rejected by the legacy contract")
				}
				return
			}
			if err != nil {
				t.Fatal("Go rejected a valid legacy input")
			}
			got.IdempotencyKey = ""
			if !reflect.DeepEqual(got, vector.Normalized) {
				t.Fatal("normalized input differs from legacy JS")
			}
			hash, err := got.intentHash()
			if err != nil || hash != vector.Hash {
				t.Fatal("canonical intent hash differs from legacy JS")
			}
		})
	}
}
